static String process(String input, Charset cs) throws IOException {
    byte[] bytes = input.getBytes(cs);
    Reader reader = new InputStreamReader(new ByteArrayInputStream(bytes), cs);
    StringBuilder sb = new StringBuilder();
    int c;
    while ((c = reader.read()) != -1) sb.append((char) c);
    reader.close();
    return sb.toString();
}

String input = "Zazolc geslą jazn";
