for (Charset cs : charsets) {
    String result = process(input, cs);
    boolean lossy = !input.equals(result);
    System.out.println(cs.name() + ": " + (lossy ? "STRATNY" : "bezstratny") + " -> " + result);
}

byte[] payload = "Wiadomosc testowa".getBytes(StandardCharsets.UTF_8);
