int type = 1;
baos.write(type);
int len = payload.length;
baos.write(len >>> 24);
baos.write(len >>> 16);
baos.write(len >>> 8);
baos.write(len);
baos.write(payload);

byte[] message = baos.toByteArray();
ByteArrayInputStream bais = new ByteArrayInputStream(message);
int readType = bais.read();
int readLen = (bais.read() << 24) | (bais.read() << 16) | (bais.read() << 8) | bais.read();
byte[] readPayload = new byte[readLen];
bais.read(readPayload);

System.out.println("Typ: " + readType);
System.out.println("Dlugosc: " + readLen);
System.out.println("Payload: " + new String(readPayload, StandardCharsets.UTF_8));
System.out.println("Poprawnosc: " + Arrays.equals(payload, readPayload));

byte[] data = new byte[64];
new Random(7).nextBytes(data);
ByteArrayInputStream bais = new ByteArrayInputStream(data);
byte[] block = new byte[16];
int offset = 0;
int read;
while ((read = bais.read(block)) != -1) {
    StringBuilder hex = new StringBuilder();
    StringBuilder ascii = new StringBuilder();
    for (int i = 0; i < read; i++) {
        hex.append(String.format("%02X ", block[i]));
        char ch = (char) (block[i] & 0xFF);
        ascii.append((ch >= 32 && ch < 127) ? ch : '.');
    }
    System.out.printf("%08X  %-48s |%s|%n", offset, hex.toString(), ascii);
    offset += read;
}

byte[] original = "Dane do przeslania".getBytes(StandardCharsets.UTF_8);
int checksum = 0;
for (byte b : original) checksum ^= b;

ByteArrayOutputStream baos = new ByteArrayOutputStream();
baos.write(original);
baos.write(checksum);
byte[] message = baos.toByteArray();

// Odbiorca:
byte[] receivedData = Arrays.copyOfRange(message, 0, message.length - 1);
int receivedChecksum = message[message.length - 1] & 0xFF;
int recalculated = 0;
for (byte b : receivedData) recalculated ^= b;

System.out.println("Otrzymana suma: " + receivedChecksum);
System.out.println("Przeliczona suma: " + (recalculated & 0xFF));
System.out.println("Dane poprawne: " + (receivedChecksum == (recalculated & 0xFF)));

String text = "To jest przykladowy dluzszy tekst do tokenizacji";
StringReader reader = new StringReader(text);
List<String> tokens = new ArrayList<>();
StringBuilder current = new StringBuilder();
int c;
try {
    while ((c = reader.read()) != -1) {
        char ch = (char) c;
        if (Character.isWhitespace(ch)) {
            if (current.length() > 0) { tokens.add(current.toString()); current.setLength(0); }
        } else {
            current.append(ch);
        }
    }
    if (current.length() > 0) tokens.add(current.toString());
} catch (IOException e) { e.printStackTrace(); }

double avgLength = tokens.stream().mapToInt(String::length).average().orElse(0);
String longest = tokens.stream().max(Comparator.comparingInt(String::length)).orElse("");

System.out.println("Liczba tokenow: " + tokens.size());
System.out.println("Srednia dlugosc: " + avgLength);
System.out.println("Najdluzszy token: " + longest);

